-- SportReserve: tabel notifikasi pelanggan + trigger status reservasi.
-- Jalankan sekali di Neon (SQL Editor). Aman dijalankan ulang.
--
-- Catatan: reservasi yang statusnya sudah berubah sebelum trigger ini dibuat
-- tidak punya notifikasi. Hanya perubahan status sesudah trigger terpasang
-- yang tercatat.

BEGIN;

CREATE TABLE IF NOT EXISTS "notifikasi" (
    "id_notifikasi" bigint GENERATED BY DEFAULT AS IDENTITY NOT NULL,
    "id_reservasi" bigint,
    "id_user" bigint NOT NULL,
    "jenis" varchar(20) DEFAULT 'info'::character varying NOT NULL,
    "judul" varchar(150) NOT NULL,
    "pesan" text NOT NULL,
    "dibaca" boolean DEFAULT false NOT NULL,
    "dibuat_pada" timestamptz DEFAULT now() NOT NULL
);

ALTER TABLE "notifikasi" ADD PRIMARY KEY ("id_notifikasi");

DO $$
BEGIN
    IF NOT EXISTS (
        SELECT 1 FROM pg_constraint
        WHERE conname = 'notifikasi_id_reservasi_fkey'
    ) THEN
        ALTER TABLE "notifikasi"
            ADD CONSTRAINT "notifikasi_id_reservasi_fkey"
            FOREIGN KEY ("id_reservasi") REFERENCES "reservasi" ("id_reservasi")
            ON DELETE CASCADE;
    END IF;

    IF NOT EXISTS (
        SELECT 1 FROM pg_constraint
        WHERE conname = 'notifikasi_id_user_fkey'
    ) THEN
        ALTER TABLE "notifikasi"
            ADD CONSTRAINT "notifikasi_id_user_fkey"
            FOREIGN KEY ("id_user") REFERENCES "users" ("id_user")
            ON DELETE CASCADE;
    END IF;

    IF NOT EXISTS (
        SELECT 1 FROM pg_constraint
        WHERE conname = 'notifikasi_jenis_check'
    ) THEN
        ALTER TABLE "notifikasi"
            ADD CONSTRAINT "notifikasi_jenis_check"
            CHECK (jenis IN ('sukses', 'ditolak', 'info'));
    END IF;
END $$;

CREATE INDEX IF NOT EXISTS idx_notifikasi_user
    ON public.notifikasi USING btree (id_user, dibaca, dibuat_pada DESC);

CREATE OR REPLACE FUNCTION notify_reservation_status()
RETURNS trigger AS $$
BEGIN
    IF NEW.status_reservasi IS DISTINCT FROM OLD.status_reservasi THEN
        IF NEW.status_reservasi = 'dikonfirmasi' THEN
            INSERT INTO notifikasi (
                id_reservasi, id_user, jenis, judul, pesan
            )
            VALUES (
                NEW.id_reservasi,
                NEW.id_user,
                'sukses',
                'Pembayaran terverifikasi',
                'Reservasi Anda telah dikonfirmasi. E-tiket sudah tersedia.'
            );
        ELSIF NEW.status_reservasi = 'dibatalkan'
              AND OLD.status_reservasi = 'menunggu' THEN
            INSERT INTO notifikasi (
                id_reservasi, id_user, jenis, judul, pesan
            )
            VALUES (
                NEW.id_reservasi,
                NEW.id_user,
                'ditolak',
                'Pembayaran ditolak',
                'Bukti pembayaran tidak dapat diverifikasi. '
                || 'Reservasi dibatalkan dan jadwal dilepas.'
            );
        END IF;
    END IF;

    RETURN NEW;
END;
$$ LANGUAGE plpgsql;

DROP TRIGGER IF EXISTS trg_notify_reservation_status ON reservasi;

CREATE TRIGGER trg_notify_reservation_status
    AFTER UPDATE OF status_reservasi ON reservasi
    FOR EACH ROW
    EXECUTE FUNCTION notify_reservation_status();

COMMIT;
